// Managed by AMP - regenerated on every start. Put your own overrides in common_local.cfg.
set hub_listenTo "{{$HubPort}}"
set jsonp_listenPort "{{$HubStatusPort}}"

// Managed by AMP - regenerated on every start. Put your own overrides in common_local.cfg.
set shard_listenTo "{{$ShardPort}}"
set net_overrideDedicatedServerAddr "{{PublicAddress}}"

#!/bin/bash
# Managed by AMP - regenerated on every update and start.
# The bundled MongoDB: MongoDB 3.4 for Linux, run natively (no Wine), everything in instance/database/:
#   database/mongodb/  binaries        database/data/  data (WiredTiger)        database/mongod.log
# 3.4 is the newest MongoDB the game's database driver works with (see the README).
#   install <version> <sha256>  update stage: downloads MongoDB's generic Linux build, unless that version is installed
#   prepare   start stage: stops a MongoDB left running, migrates old MongoDB 2.6 data once, restarts the Wine server
#   start     hub-wrapper.sh, before Hub: starts MongoDB and waits until it accepts connections
#   stop      hub-wrapper.sh, after Hub: shuts MongoDB down cleanly
#   external  start stage: waits for External MongoDB Hosts
#   roles <host:port> <admin uids> <moderator uids>  hub-wrapper.sh, before Hub: the Admin and Moderator roles
#   account <host:port> <uid or name>                console "player": shows an account
#   task <host:port> <fields>                        console "give": runs an admin task on Shard
ROOT='{{$FullRootDir}}'
BASE='{{$FullBaseDir}}'
DB="${BASE}database"
BIN="$DB/mongodb/bin"
DATA="$DB/data"
PID="$DB/mongod.pid"
PORT='{{$MongoPort}}'
export WINEPREFIX="${ROOT}.wine" WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree,mshtml='
WINESERVER="$(dirname "$(readlink -f /usr/bin/wine)")/wineserver"

port_open() { (exec 3<>"/dev/tcp/127.0.0.1/$1") 2>/dev/null; }
free_port() { local p=$1; while port_open "$p"; do p=$((p + 1)); done; echo "$p"; }
running() { [ -s "$PID" ] && ps -p "$(cat "$PID")" -o args= 2>/dev/null | grep -q '[m]ongod '; }
wine_mongod_running() { ps -eo args | grep -q '^[^ ]*[m]ongod\.exe'; }
empty_data() { rm -rf "${DATA:?}" && mkdir -p "$DATA"; }

stop_mongod() {
  running || { rm -f "$PID"; return 0; }
  echo 'Stopping MongoDB'
  kill -TERM "$(cat "$PID")"
  for i in $(seq 1 60); do running || { rm -f "$PID"; return 0; }; sleep 1; done
  echo 'WARNING: MongoDB did not stop within 60s'
  return 1
}

start_mongod() {
  [ -x "$BIN/mongod" ] || { echo "MongoDB is not installed in $DB/mongodb: update the instance. Aborting"; return 1; }
  running && { echo 'MongoDB is already running'; return 0; }
  port_open "$PORT" && { echo "Port $PORT (MongoDB Port) is already in use by something else. Aborting"; return 1; }
  mkdir -p "$DATA"
  local cache; cache=$(printf '%s' '{{MongoCacheSizeGB}}' | tr , .)
  awk -v c="$cache" 'BEGIN { exit !(c ~ /^[0-9]*[.]?[0-9]+$/ && c + 0 >= 0.25) }' \
    || { echo "MongoDB Cache Size (GB) '{{MongoCacheSizeGB}}' is not a number of at least 0.25, using 1"; cache=1; }
  "$BIN/mongod" --dbpath "$DATA" --bind_ip 127.0.0.1 --port "$PORT" --wiredTigerCacheSizeGB "$cache" \
    --logpath "$DB/mongod.log" --logappend --pidfilepath "$PID" --fork >/dev/null \
    || { tail -n 5 "$DB/mongod.log"; echo 'MongoDB did not start, see database/mongod.log. Aborting'; return 1; }
  for i in $(seq 1 60); do port_open "$PORT" && { echo "MongoDB is up on 127.0.0.1:$PORT"; return 0; }; sleep 1; done
  echo 'MongoDB did not accept connections within 60s, see database/mongod.log. Aborting'
  return 1
}

# Template versions before 2.0 ran the MongoDB 2.6 that ships with the server under Wine, with its data in
# server/mongo-data (before 1.12: star-conflict/mongo-data). That data is copied into database/data once, here: the old
# mongod.exe serves it on a spare port, and the 3.4 tools dump it into a temporary 3.4 on another one.
# database/data/.migrated records it. The old folder is left as it is.
migrate() {
  local old='' d
  for d in "${BASE}server/mongo-data" "${ROOT}mongo-data"; do
    ls "$d"/*.ns >/dev/null 2>&1 && { old=$d; break; }
  done
  [ -n "$old" ] || return 0
  [ -e "$DATA/.migrated" ] && return 0
  if [ -n "$(ls -A "$DATA" 2>/dev/null)" ]; then
    echo "Note: $old holds MongoDB 2.6 data that was not migrated, because database/data already has data"
    return 0
  fi
  [ -x "$BIN/mongod" ] || { echo "MongoDB is not installed in $DB/mongodb: update the instance. Aborting"; return 1; }
  local m26="${BASE}server/cloud/mongodb"
  [ -f "$m26/mongod.exe" ] || { echo "$old needs MongoDB 2.6 to be read, but server/cloud/mongodb/mongod.exe is missing. Aborting"; return 1; }
  echo "Migrating the MongoDB 2.6 data in $old to MongoDB 3.4 in database/data (once; the old folder stays as it is)"
  # A non-empty lock with no journal files is left by a clean shutdown that was cut off after its final commit.
  if [ -s "$old/mongod.lock" ] && ! ls "$old"/journal/j._* >/dev/null 2>&1; then : > "$old/mongod.lock"; fi
  local src dst log="$DB/migrate.log" status dbs ok=1
  src=$(free_port 27100)
  (cd "$m26" && exec /usr/bin/wine mongod.exe --dbpath "Z:$old" --bind_ip 127.0.0.1 --port "$src" --smallfiles --logpath "Z:$old/mongod.log" --logappend) >/dev/null 2>&1 &
  for i in $(seq 1 90); do port_open "$src" && break; sleep 1; done
  if ! port_open "$src"; then
    echo "MongoDB 2.6 did not start on the old data, see $old/mongod.log. Aborting"
    "$WINESERVER" -k 2>/dev/null
    return 1
  fi
  dst=$(free_port $((src + 1)))
  mkdir -p "$DATA"
  : > "$log"
  if "$BIN/mongod" --dbpath "$DATA" --bind_ip 127.0.0.1 --port "$dst" --wiredTigerCacheSizeGB 0.25 --logpath "$DB/migrate-mongod.log" --fork >/dev/null; then
    # admin holds 2.6's users and auth schema, which the game doesn't use.
    "$BIN/mongodump" --host "127.0.0.1:$src" --archive 2>>"$log" | "$BIN/mongorestore" --host "127.0.0.1:$dst" --archive --nsExclude 'admin.*' 2>>"$log"
    status=("${PIPESTATUS[@]}")
    dbs=$("$BIN/mongo" --port "$dst" --quiet --eval 'db.adminCommand("listDatabases").databases.forEach(function (d) { if (d.name != "admin" && d.name != "local") print(d.name); })' 2>/dev/null | tr '\n' ' ')
    [ "${status[0]}" -eq 0 ] && [ "${status[1]}" -eq 0 ] && [ -n "$dbs" ] && ok=0
    "$BIN/mongod" --dbpath "$DATA" --shutdown >/dev/null
  else
    echo 'Temporary MongoDB 3.4 did not start, see database/migrate-mongod.log' >>"$log"
  fi
  "$BIN/mongo" --port "$src" --quiet --eval "db.getSiblingDB('admin').shutdownServer()" >/dev/null 2>&1
  for i in $(seq 1 60); do wine_mongod_running || break; sleep 1; done
  if [ $ok -ne 0 ]; then
    tail -n 20 "$log"
    echo 'Migrating the MongoDB data failed (full output in database/migrate.log). database/data was emptied again; the old data is untouched. Aborting'
    empty_data
    return 1
  fi
  echo "$old on $(date -u '+%Y-%m-%d %H:%M UTC'): $dbs" > "$DATA/.migrated"
  echo "Migrated: $dbs"
  echo "Once the server runs fine, $old can be deleted"
}

case "$1" in
  install)
    version=$2 sha=$3
    mkdir -p "$DATA"
    if [ -x "$BIN/mongod" ] && "$BIN/mongod" --version | grep -q "^db version v$version\$"; then
      echo "MongoDB $version is already installed"; exit 0
    fi
    tgz="$DB/mongodb.tgz"
    echo "Downloading MongoDB $version"
    wget -nv -O "$tgz" "https://fastdl.mongodb.org/linux/mongodb-linux-x86_64-$version.tgz" || { rm -f "$tgz"; echo 'MongoDB download failed. Aborting'; exit 1; }
    echo "$sha  $tgz" | sha256sum -c --quiet - || { rm -f "$tgz"; echo 'MongoDB download has the wrong checksum. Aborting'; exit 1; }
    rm -rf "$DB/mongodb" && mkdir -p "$DB/mongodb" && tar -xzf "$tgz" -C "$DB/mongodb" --strip-components=1 || { rm -f "$tgz"; echo 'Extracting MongoDB failed. Aborting'; exit 1; }
    rm -f "$tgz"
    echo "MongoDB $version installed in database/mongodb"
    ;;
  prepare)
    # A MongoDB from a run whose hub-wrapper.sh was killed before it could stop it.
    stop_mongod || exit 1
    # The Wine MongoDB 2.6 of template versions before 2.0, which kept running after Hub stopped.
    if wine_mongod_running; then
      echo 'Stopping the old Wine MongoDB 2.6'
      [ -x "$BIN/mongo" ] && "$BIN/mongo" --port "$PORT" --quiet --eval "db.getSiblingDB('admin').shutdownServer()" >/dev/null 2>&1
      for i in $(seq 1 60); do wine_mongod_running || break; sleep 1; done
    fi
    if [ '{{MongoMode}}' != external ]; then migrate || exit 1; fi
    # Restarting the Wine server clears services and sockets left over from the last run.
    echo 'Restarting the Wine server'
    "$WINESERVER" -k 2>/dev/null
    "$WINESERVER" -w 2>/dev/null
    ;;
  roles)
    # Shard reads the roles from web_adm.admRoles, one document { roles: { <role>: { <privilege>: true, ... } } },
    # once at startup, and an account's role from its admRole field ("player" by default). Privileges are the admin
    # task names (mute, ban, ...) plus general ones: gmView covers GM tools such as playerInfo and changeNickName,
    # adminEdit destructive edits such as resetStats, playInMaintenance logging in during maintenance. So this runs
    # before Hub starts. Accounts that lose their listing become "player" again; other roles are left alone.
    host=$2
    admins=$(printf '%s' "$3" | tr -c '0-9' ' ')
    mods=$(printf '%s' "$4" | tr -c '0-9' ' ')
    [ -x "$BIN/mongo" ] || { echo 'Roles: MongoDB shell not installed (update the instance), skipped'; exit 0; }
    quoted() { local x out=''; for x in $1; do out="$out'$x',"; done; echo "[${out%,}]"; }
    js=$(mktemp)
    cat > "$js" <<'JS'
function obj(names) { var o = {}; names.split(' ').forEach(function (n) { o[n] = true; }); return o; }
var w = db.getSiblingDB('web_adm');
var roles = { admin: obj(PRIV_ADMIN), moderator: obj(PRIV_MOD) };
var doc = w.admRoles.findOne();
if (doc) w.admRoles.update({ _id: doc._id }, { $set: { 'roles.admin': roles.admin, 'roles.moderator': roles.moderator } });
else w.admRoles.insert({ roles: roles });
var acc = db.getSiblingDB(GAME_DB).accounts;
var want = {};
MODS.forEach(function (u) { want[u] = 'moderator'; });
ADMINS.forEach(function (u) { want[u] = 'admin'; });
acc.find({ admRole: { $in: ['admin', 'moderator'] } }, { uid: 1, admRole: 1, nickName: 1 }).forEach(function (a) {
  var u = String(a.uid.toNumber ? a.uid.toNumber() : a.uid);
  if (!want[u]) {
    acc.update({ _id: a._id }, { $set: { admRole: 'player' }, $inc: { ver: NumberLong(1) } });
    print('Roles: uid ' + u + ' (' + a.nickName + ') is a player again');
  }
});
Object.keys(want).forEach(function (u) {
  var a = acc.findOne({ uid: NumberLong(u) }, { admRole: 1, nickName: 1 });
  if (!a) { print('Roles: WARNING: no account with uid ' + u + ' (it is created at the first login)'); return; }
  if (a.admRole !== want[u]) acc.update({ _id: a._id }, { $set: { admRole: want[u] }, $inc: { ver: NumberLong(1) } });
  print('Roles: uid ' + u + ' (' + a.nickName + ') is ' + want[u]);
});
JS
    "$BIN/mongo" --quiet "$host/web_adm" \
      --eval "var GAME_DB='cosmosim_$(id -un)', ADMINS=$(quoted "$admins"), MODS=$(quoted "$mods"), PRIV_ADMIN='giveAutogenModule giveTestAutogenModule questServerExecConsoleCmd setStat setUnlimPveMissionLevel setIsSingleUidOnPC unsetIsSingleUidOnPC removeNewbieAura giveSpecModule unlockAllVesselNodes sendCheatToUniverse rotateLeagueTeam banLeagueTeam removeLeagueTeam updateLeagueTeams changeLeagueTeamName createAccountFromPattern setSuspicionUser resetUniversesCounter giveFreeSpace giveVesselCustomElement giveTitle giveClanShipModule setClanResource restoreClan removeClan changeClanTag renameClan setClanRole createClan linkServices changeServiceId unlinkService togglePromo changeNickName changeUsername createAccount forgetAccount resetAccount copyNewAccount copyAccount resetStats resetAchievements leaveMMode enterMMode unequip delete gamesInfo assignRolePrivileges assignRole playerInfo cancelMute mutePermanent mute cancelBan banPermanent ban play playInMaintenance gmView propertyEdit adminView adminEdit privilegesControl promoControl observeGames playFreeSpace playClosedPTR roleAssignment', PRIV_MOD='mute mutePermanent cancelMute ban banPermanent cancelBan play playInMaintenance observeGames';" "$js" \
      || echo 'Roles: WARNING: could not update the roles'
    rm -f "$js"
    ;;
  account)
    # account <host:port> <uid or name>: an account's role, currencies, premium, bans, ships and items
    host=$2
    who=$(printf '%s' "$3" | tr -cd 'A-Za-z0-9_.@-')
    [ -n "$who" ] || { echo 'usage: player <uid or name>'; exit 1; }
    [ -x "$BIN/mongo" ] || { echo 'MongoDB shell not installed (update the instance)'; exit 1; }
    js=$(cat <<'JS'
var q = /^[0-9]+$/.test(WHO) ? { uid: NumberLong(WHO) } : { $or: [ { nickName: new RegExp("^" + WHO.replace(/\./g, "\\.") + "$", "i") }, { username: WHO } ] };
var a = db.accounts.findOne(q);
if (!a) { print("No account " + WHO); quit(0); }
var now = Date.now(), n = function (v) { return v && v.toNumber ? v.toNumber() : (v || 0); };
var when = function (v) { return n(v) > now ? "until " + new Date(n(v)).toISOString().slice(0, 16).replace("T", " ") + " UTC" : "no"; };
print("uid " + n(a.uid) + ", nickname " + a.nickName + ", username " + a.username + ", role " + a.admRole);
print("GS " + n(a.goldCredits) + ", credits " + n(a.credits) + ", tokens " + n(a.tokenCredits) + ", premium " + when(a.premiumTill));
print("banned " + when(a.bannedTill) + ", chat muted " + when(a.chatMutedTill));
var ships = (a.vessels || []).map(function (v) { return v.defName; });
print("ships (" + ships.length + "): " + (ships.slice(0, 12).join(", ") || "none") + (ships.length > 12 ? ", ..." : ""));
print("items " + (a.items || []).length + ", titles " + (a.acquiredTitles || []).length + (a.title ? " (current " + n(a.title) + ")" : ""));
JS
)
    "$BIN/mongo" --quiet "$host/cosmosim_$(id -un)" --eval "var WHO='$who'; $js"
    ;;
  task)
    # task <host:port> <fields>: queues an admin task for Shard (the old web panel's mechanism) and waits for the result.
    # Shard picks tasks from adminTasks every 5 seconds; "gaijin_gdpr" is the service allowed to queue without an account.
    host=$2
    [ -x "$BIN/mongo" ] || { echo 'MongoDB shell not installed (update the instance)'; exit 1; }
    js=$(cat <<'JS'
var t = Object.assign({ _id: ObjectId(), serviceType: NumberInt(2), pickedBy: NumberLong(0), requestedByService: "gaijin_gdpr" }, FIELDS);
db.adminTasks.insert(t);
for (var i = 0; i < 60; i++) {
  var d = db.adminTasks.findOne({ _id: t._id, finishedAt: { $exists: true } });
  if (d) {
    print(d.success ? "done" : "failed: " + d.errMsg);
    if (d.result) printjson(d.result);
    db.adminTasks.remove({ _id: t._id });
    quit(0);
  }
  sleep(500);
}
db.adminTasks.remove({ _id: t._id, pickedBy: NumberLong(0) });
print("Shard did not pick up the task within 30 seconds (is the server running?)");
JS
)
    "$BIN/mongo" --quiet "$host/cosmosim_$(id -un)" --eval "var FIELDS = $3; $js"
    ;;
  start)
    start_mongod
    ;;
  stop)
    stop_mongod
    ;;
  external)
    # Waits until one host of the first host group in External MongoDB Hosts accepts connections.
    # Format (db_mongoHosts): host1[:port],host2[:port]|options;group2...
    HOSTS='{{MongoHosts}}'
    HOSTS=${HOSTS%%;*}; HOSTS=${HOSTS%%|*}
    [ -n "$HOSTS" ] || { echo 'External MongoDB Hosts is empty. Aborting'; exit 1; }
    IFS=, read -r -a LIST <<< "$HOSTS"
    for i in $(seq 1 30); do
      for h in "${LIST[@]}"; do
        h=${h// /}; host=${h%:*}; port=${h##*:}; [ "$port" = "$h" ] && port=27017
        if (exec 3<>"/dev/tcp/$host/$port") 2>/dev/null; then echo "External MongoDB is up at $host:$port"; exit 0; fi
      done
      sleep 2
    done
    echo "External MongoDB ($HOSTS) did not accept connections within 60s. Aborting"
    exit 1
    ;;
  *)
    echo "usage: $0 install <version> <sha256> | prepare | start | stop | external | roles <host:port> <admin uids> <moderator uids> | account <host:port> <uid or name> | task <host:port> <fields>"
    exit 1
    ;;
esac
